(5678563, 825555, 70270, '<td valign="top">Can''t say I like the composition all that much, butnice exposure control and a good fit to the challenge bump this to a 6</td>', 'Can''t say I like the composition all that much, butnice exposure control and a good fit to the challenge bump this to a 6', '2009-10-07 14:42:37.000000', NULL, 1),
