(5686729, 826136, 30982, '<td valign="top">Good job on beating your mom!  (Some of the folks not in the United States might not "get it" since they don''t know the "old" pennies have a different back.)</td>', 'Good job on beating your mom!  (Some of the folks not in the United States might not "get it" since they don''t know the "old" pennies have a different back.)', '2009-10-14 09:53:32.000000', NULL, 0),
(5686741, 826203, 59276, '<td valign="top">Congrats on the win!!! I''m happy to hear that you took this in the last hour of the challenge. Thanks for the story of how you got the lighting right. Just love it!</td>', 'Congrats on the win!!! I''m happy to hear that you took this in the last hour of the challenge. Thanks for the story of how you got the lighting right. Just love it!', '2009-10-14 10:02:42.000000', NULL, 0),
(5686754, 826203, 8891, '<td valign="top">Excellent work, Joe! Big congrats on your yellow!</td>', 'Excellent work, Joe! Big congrats on your yellow!', '2009-10-14 10:10:52.000000', NULL, 0),
